function timebox(tasks, total, opts){
  opts=opts||{};
  var lines=(typeof tasks==='string' ? tasks.split(/\n/) : (tasks||[]))
    .map(function(s){ return String(s).trim(); }).filter(Boolean);
  if(!lines.length) return {ok:false, reason:'请输入至少一个任务'};
  total=Number(total);
  if(!isFinite(total) || !(total>0)) return {ok:false, reason:'总时长需 > 0'};
  var names=[], weights=[];
  for(var i=0;i<lines.length;i++){
    var p=lines[i].split(/\s*[:：]\s*/);
    var w=p.length>1 ? Number(p[p.length-1]) : 1;
    if(!isFinite(w) || w<0) w=1;
    names.push(p.length>1 ? p.slice(0,-1).join(' ').trim() : lines[i]);
    weights.push(w);
  }
  var tw=0;
  for(var j=0;j<weights.length;j++) tw+=weights[j];
  if(!(tw>0)){ for(var q=0;q<weights.length;q++) weights[q]=1; tw=weights.length; }
  var minSlot=opts.minSlot!=null?Number(opts.minSlot):0;
  if(!isFinite(minSlot) || minSlot<0) minSlot=0;
  var out=[], allocated=0;
  for(var k=0;k<names.length;k++){
    var v=total*weights[k]/tw;
    if(minSlot>0 && v<minSlot) v=minSlot;
    if(opts.round) v=Math.round(v);
    out.push({task:names[k], weight:weights[k], minutes:v});
    allocated+=v;
  }
  return {ok:true, items:out, total:total, allocated:allocated, unit:opts.unit||'min', count:out.length};
}

var EXPORTS={timebox:timebox};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TimeboxForgePure = EXPORTS; }
